<!--
 * 部门管理页面 — 树形表格展示部门层级，支持新增（顶级/子级）/编辑/删除部门
 *
 * @path apps\userinfo-web\src\views\system\dept\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 部门（列表页）
 * <p>部门（{@code ydsz_dept}）的列表页，消费后端契约 DepartmentController
 * （src/api/department.ts，auto-generated by bash/gen-contract.py）：
 * 以 tree() 获取带 children 的部门树直接渲染树形表格，支持新增顶级/子级部门、
 * 编辑与删除，删除成功后刷新树。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButtonBase } from '@ydsz-core/ydsz-ui';
import { YdTable } from '@ydsz-core/ydsz-ui';
import { ElTableColumn } from 'element-plus';
import { onMounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@ydsz-core/shared/utils';

import { remove, tree } from '#/api/department';
import type { DepartmentTreeVO } from '#/api/models';

import DeptForm from './dept-form.vue';

defineOptions({ name: 'DeptManagement' });

const logger = createLogger('userinfo-dept');
const { t } = useI18n();

/** 判断部门状态是否启用（契约 status 为字符串 '1'/'0'） */
function isEnabled(status?: string): boolean {
  return status === '1';
}

const loading = ref(false);
const tableData = ref<DepartmentTreeVO[]>([]);

async function loadData() {
  loading.value = true;
  try {
    tableData.value = (await tree()) ?? [];
  } finally {
    loading.value = false;
  }
}

onMounted(loadData);

// ========== 表单弹窗 ==========
const [DeptFormModal, deptFormApi] = useYdModal({
  connectedComponent: DeptForm,
});

function handleAdd(parentId?: string) {
  deptFormApi.setData({
    parentId,
    treeData: tableData.value,
  });
  deptFormApi.open();
}

function handleEdit(row: DepartmentTreeVO) {
  deptFormApi.setData({
    record: row,
    treeData: tableData.value,
  });
  deptFormApi.open();
}

// ========== 删除 ==========
async function handleDelete(row: DepartmentTreeVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(
      t('dept.deleteDeptConfirm', { deptName: row.deptName ?? '' }),
      t('page.confirmDelete'),
      { type: 'warning' },
    );
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await remove({ id: row.id });
    showToast.success(t('page.deleteSuccess'));
    loadData();
  } catch (error) {
    logger.warn('删除部门失败: {}', error);
  }
}
</script>

<template>
  <Page auto-content-height>
    <div class="p-4">
      <div class="mb-4 flex items-center justify-between">
        <h3 class="text-lg font-semibold">{{ t('dept.deptManagement') }}</h3>
        <div class="flex gap-2">
          <YdButtonBase variant="ghost" @click="loadData">{{ t('page.refresh') }}</YdButtonBase>
          <YdButtonBase variant="default" @click="handleAdd()">{{ t('dept.addTopDept') }}</YdButtonBase>
        </div>
      </div>
      <YdTable
        v-loading="loading"
        :data="tableData"
        row-key="id"
        border
        default-expand-all
        :tree-props="{ children: 'children' }"
      >
        <ElTableColumn prop="deptName" :label="t('page.deptName')" min-width="200" />
        <ElTableColumn prop="deptCode" :label="t('dept.deptCode')" width="140" />
        <ElTableColumn prop="description" :label="t('page.description')" min-width="180" />
        <ElTableColumn prop="sortOrder" :label="t('page.sortOrder')" width="80" align="center" />
        <ElTableColumn :label="t('page.status')" width="80" align="center">
          <template #default="{ row }">
            <YdBadge :variant="isEnabled(row.status) ? 'default' : 'destructive'" :class="isEnabled(row.status) ? 'bg-green-500 text-white hover:bg-green-600' : ''" class="text-xs">
              {{ isEnabled(row.status) ? t('page.enabled') : t('page.disabled') }}
            </YdBadge>
          </template>
        </ElTableColumn>
        <ElTableColumn :label="t('page.operation')" width="240" fixed="right">
          <template #default="{ row }">
            <YdButtonBase size="sm" variant="link" @click="handleAdd(row.id)">
              {{ t('dept.addSubDept') }}
            </YdButtonBase>
            <YdButtonBase size="sm" variant="link" @click="handleEdit(row)">
              {{ t('page.edit') }}
            </YdButtonBase>
            <YdButtonBase size="sm" variant="link" class="text-destructive" @click="handleDelete(row)">
              {{ t('page.delete') }}
            </YdButtonBase>
          </template>
        </ElTableColumn>
      </YdTable>
    </div>
    <DeptFormModal @success="loadData" />
  </Page>
</template>